if(!exists('estimate_tranche_credit_metrics'))library(creditratingsystem)
spa_D<-'2023-01-01';spa_dates<-list('2023-07-01','2024-01-01')
spa_asset<-function(id='a',group='g')list(asset_id=id,asset_class='AUTO_LOAN',invoice_id=NULL,obligor_id=group,default_group_id=group,seller_id='seller',servicer_id='service',currency='EUR',observed_at=spa_D,known_at=spa_D,origination_date='2022-01-01',balance_date=spa_D,principal_balance=100,schedule=list(list(date=spa_dates[[1]],principal_due=40,interest_due=5),list(date=spa_dates[[2]],principal_due=60,interest_due=3)),overdue_days=0,disputed=FALSE,dilution_reserve=0,recourse='NONE',collateral_allocations=list())
spa_assignment<-function(id='m',aid='a',start=spa_D,price=100)list(assignment_id=id,pool_id='pool',asset_id=aid,known_at=spa_D,effective_from=start,effective_until=NULL,share=1,purchase_price=price,purchase_priority=1)
spa_fixture<-function(assets=list(spa_asset()),assignments=list(spa_assignment()),revolving=FALSE){
 p<-list(profile_id='p',version='1',known_at=spa_D,currency='EUR',product_kind='ABS',pool_mode=if(revolving)'REVOLVING'else'STATIC',allowed_asset_classes=list('AUTO_LOAN'),maximum_dpd=30,exclude_disputed=TRUE,eligible_recourse=list('NONE'),revolving_until=if(revolving)spa_dates[[2]]else NULL)
 pool<-build_credit_asset_pool(assets,assignments,p,'pool',spa_D,spa_D)$value
 contract<-list(contract_id='c',version='1',scenario_ids=list('s'),weights=list(1),dates=spa_dates,currency='EUR',probability_measure='PHYSICAL',sampling_design='FIXED_WEIGHTED_SCENARIOS',conditioning='PIT',default_timing='BEFORE_DUE',prepayment_timing='AFTER_COUPON',dilution_treatment='PROPORTIONAL_REMAINING_SCHEDULE',reinvestment_funding='PRINCIPAL_CASH_ONLY',initial_reinvestment_cash=0)
 gp<-ap<-innov<-list();for(g in sort(unique(vapply(assets,function(a)a$default_group_id,''))))for(d in spa_dates){gp[[length(gp)+1L]]<-list(scenario_id='s',default_group_id=g,date=d,conditional_pd=0,default_channel=paste0('default-',g));innov[[length(innov)+1L]]<-list(scenario_id='s',date=d,channel_id=paste0('default-',g),uniform=.5)}
 for(a in assets)for(d in spa_dates){ap[[length(ap)+1L]]<-list(scenario_id='s',asset_id=a$asset_id,date=d,conditional_prepayment_probability=0,prepayment_channel=paste0('prepay-',a$asset_id),dilution_fraction=0,recovery_fraction=.4,recovery_delay_days=30,recovery_cost=5,servicing_cost=0,interest_multiplier=1,overdue_days=0,disputed=FALSE);innov[[length(innov)+1L]]<-list(scenario_id='s',date=d,channel_id=paste0('prepay-',a$asset_id),uniform=.5)}
 list(asset_pool=pool,scenario_contract=contract,obligor_paths=gp,asset_paths=ap,shared_innovations=innov)
}
spa_run<-function(f)do.call(simulate_asset_pool,f)$value
spa_total<-function(r,key)sum(vapply(r$cashflows,function(c)c[[key]],0.))
spa_error<-function(code,expr){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),e$code==code)}

sw_profile<-function()list(structure_id='senior-junior',version='1',currency='EUR',payment_dates=spa_dates,tranches=list(list(tranche_id='senior',seniority=1,notional=80,legal_maturity=spa_dates[[2]],coupon_fractions=setNames(list(.05,.05),unlist(spa_dates))),list(tranche_id='junior',seniority=2,notional=20,legal_maturity=spa_dates[[2]],coupon_fractions=setNames(list(.05,.05),unlist(spa_dates)))),fees=setNames(list(0,0),unlist(spa_dates)),initial_reserve=0,reserve_target=0,liquidity_limit=0,principal_mode='SEQUENTIAL',principal_for_interest='TRIGGER_ONLY',excess_interest_to_principal=TRUE,trigger_seniority=1,oc_threshold=1,ic_threshold=1,terminal_policy='REQUIRE_COMPLETE')
sw_run<-function(p=sw_profile(),paths=spa_run(spa_fixture()))run_tranche_waterfall(paths,p)$value

sm_target<-function(event='ULTIMATE_PRINCIPAL')list(event=event,horizon=365,time_unit='days',probability_measure='PHYSICAL',conditioning='PIT')
sm_df<-setNames(list(1,1),unlist(spa_dates))
sm_metric<-function(w=sw_run(),event='ULTIMATE_PRINCIPAL',df=sm_df)estimate_tranche_credit_metrics(w,sm_target(event),df)$value
f<-spa_fixture();f$scenario_contract$sampling_design<-'IID_UNWEIGHTED';r<-sm_metric(sw_run(paths=spa_run(f)));m<-r$metrics[[1]];stopifnot(m$event_probability==0,m$expected_ultimate_principal_loss==0,max(abs(unlist(m$event_probability_interval)-c(0,.975)))<1e-12,is.null(m$discounted_cash_shortfall_mcse))
p<-sw_profile();p$principal_for_interest<-'NEVER';p$oc_threshold<-p$ic_threshold<-0;f<-spa_fixture();f$asset_paths[[1]]$interest_multiplier<-0;f$asset_paths[[2]]$interest_multiplier<-4;w<-sw_run(p,spa_run(f));a<-sm_metric(w,'TIMELY_INTEREST');b<-sm_metric(w);stopifnot(all(vapply(a$metrics,function(m)m$event_probability==1&&m$expected_discounted_contractual_cash_shortfall==0,TRUE)),all(vapply(b$metrics,function(m)m$event_probability==0&&m$expected_ultimate_principal_loss==0,TRUE)))
f<-spa_fixture();f$obligor_paths[[1]]$conditional_pd<-1;p<-sw_profile();for(i in 1:2)p$tranches[[i]]$coupon_fractions<-setNames(list(0,0),unlist(spa_dates));r<-sm_metric(sw_run(p,spa_run(f)),'TIMELY_INTEREST');a<-r$metrics[[1]];b<-r$metrics[[2]];stopifnot(a$event_probability==0,a$expected_ultimate_principal_loss==45,a$expected_principal_loss_outside_selected_event==45,is.null(a$conditional_principal_loss_given_selected_event),b$expected_ultimate_principal_loss==20,a$expected_discounted_contractual_cash_shortfall==45)
p<-sw_profile();p$tranches<-list(list(tranche_id='senior',seniority=1,notional=100,legal_maturity=spa_dates[[2]],coupon_fractions=setNames(list(.05,0),unlist(spa_dates))));p$principal_for_interest<-'NEVER';p$oc_threshold<-p$ic_threshold<-0;f<-spa_fixture();f$asset_paths[[1]]$interest_multiplier<-0;f$asset_paths[[2]]$interest_multiplier<-2;r<-sm_metric(sw_run(p,spa_run(f)),'TIMELY_INTEREST',setNames(list(1,.9),unlist(spa_dates)));stopifnot(r$metrics[[1]]$expected_ultimate_principal_loss==0,r$metrics[[1]]$event_probability==1,abs(r$metrics[[1]]$expected_discounted_contractual_cash_shortfall-.5)<1e-12)
f<-spa_fixture();f$scenario_contract$scenario_ids<-list('s','t');f$scenario_contract$weights<-list(.75,.25);for(name in c('obligor_paths','asset_paths','shared_innovations')){extra<-f[[name]];for(i in seq_along(extra))extra[[i]]$scenario_id<-'t';f[[name]]<-c(f[[name]],extra)};f$obligor_paths[[3]]$conditional_pd<-1;p<-sw_profile();for(i in 1:2)p$tranches[[i]]$coupon_fractions<-setNames(list(0,0),unlist(spa_dates));r<-sm_metric(sw_run(p,spa_run(f)));m<-r$metrics[[1]];stopifnot(m$event_probability==.25,m$expected_ultimate_principal_loss==11.25,m$conditional_principal_loss_given_selected_event==45,is.null(m$event_probability_interval))
base<-sw_run();p<-sw_profile();p$initial_reserve<-10;alt<-sw_run(p);r<-stress_tranche_structure(base,list(list(alternative_id='reserve',tranche_paths=alt,assumption='External funded support ten')),sm_target(),sm_df)$value;stopifnot(r$comparisons[[1]]$deltas[[1]]$changes$event_probability==0);f<-spa_fixture();f$shared_innovations[[1]]$uniform<-.6;other<-sw_run(paths=spa_run(f));spa_error('STRUCTURED_SHARED_PATHS',stress_tranche_structure(base,list(list(alternative_id='bad',tranche_paths=other,assumption='Unpaired')),sm_target(),sm_df))
f<-spa_fixture();f$obligor_paths[[1]]$conditional_pd<-1;f$asset_paths[[1]]$recovery_delay_days<-1000;p<-sw_profile();p$terminal_policy<-'KEEP_OPEN';w<-sw_run(p,spa_run(f));spa_error('STRUCTURED_UNRESOLVED',sm_metric(w));stopifnot(is.null(sm_metric(w,'TIMELY_INTEREST')$metrics[[1]]$expected_ultimate_principal_loss));bad<-sm_target();bad$horizon<-1;spa_error('TARGET_MISMATCH',estimate_tranche_credit_metrics(sw_run(),bad,sm_df));spa_error('STRUCTURED_DISCOUNT',estimate_tranche_credit_metrics(sw_run(),sm_target(),sm_df[1]))
cat('Native separate event targets, discounted timing loss and paired structure stress PASS\n')
f<-spa_fixture(list(spa_asset(),spa_asset('b','h')),list(spa_assignment(),spa_assignment('b','b')));f$scenario_contract$scenario_ids<-list('s','t');f$scenario_contract$weights<-list(.5,.5);for(name in c('obligor_paths','asset_paths','shared_innovations')){extra<-f[[name]];for(i in seq_along(extra))extra[[i]]$scenario_id<-'t';f[[name]]<-c(f[[name]],extra)}
for(i in seq_along(f$obligor_paths))f$obligor_paths[[i]]$conditional_pd<-if(f$obligor_paths[[i]]$date==spa_dates[[1]]).5 else 0
for(i in seq_along(f$asset_paths)){f$asset_paths[[i]]$recovery_fraction<-0;f$asset_paths[[i]]$recovery_cost<-0;f$asset_paths[[i]]$interest_multiplier<-0;if(f$asset_paths[[i]]$asset_id=='b')f$asset_paths[[i]]$prepayment_channel<-'default-h'}
f$shared_innovations<-Filter(function(x)x$channel_id!='prepay-b',f$shared_innovations);for(i in seq_along(f$shared_innovations)){row<-f$shared_innovations[[i]];if(row$channel_id=='default-g')f$shared_innovations[[i]]$uniform<-if(row$scenario_id=='s').25 else .75;if(row$channel_id=='default-h')f$shared_innovations[[i]]$uniform<-if(row$scenario_id=='s').75 else .25}
p<-sw_profile();p$tranches[[1]]$notional<-180;for(i in 1:2)p$tranches[[i]]$coupon_fractions<-setNames(list(0,0),unlist(spa_dates));anti<-sw_run(p,spa_run(f));positive<-f;for(i in seq_along(positive$obligor_paths))if(positive$obligor_paths[[i]]$default_group_id=='h')positive$obligor_paths[[i]]$default_channel<-'default-g';joint<-sw_run(p,spa_run(positive));r<-stress_tranche_structure(anti,list(list(alternative_id='joint',tranche_paths=joint,assumption='Same marginal defaults with shared innovation')),sm_target(),sm_df)$value;a<-r$baseline$metrics;b<-r$comparisons[[1]]$metrics$metrics;stopifnot(identical(vapply(a,function(x)x$expected_ultimate_principal_loss,0.),c(80,20)),identical(vapply(b,function(x)x$expected_ultimate_principal_loss,0.),c(90,10)),all(vapply(a,function(x)x$event_probability==1,TRUE)),all(vapply(b,function(x)x$event_probability==.5,TRUE)))
